{
  "title": "神秘的森林小屋",
  "scene": "你漫步在一片密林之中，四周是茂密的树木和浓重的雾气。忽然，一座陈旧的小屋映入眼帘，门半开着，透出微弱的烛光。小屋的窗户上挂着厚重的窗帘，几乎遮住了所有的光线。你隐约听到屋内传来低沉的对话声，似乎是在谈论着什么重要的事情。你的好奇心被勾起，但你又担心贸然闯入会带来不必要的麻烦。",
  "goal": "调查小屋内发生的事情",
  "clue": "烛光和低沉的对话声暗示屋内有人，但窗帘遮光可能是不想被人发现。",
  "choices": [
    {
      "id": "A",
      "text": "直接推门进去",
      "outcome": "你推开门，屋内的两个人立刻停下了对话，冷冷地盯着你。他们显然不欢迎不速之客。虽然他们没有攻击你，但你感到气氛十分紧张，似乎错过了什么重要的事情。",
      "result": "fail",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "轻声敲门",
      "outcome": "你轻轻敲了敲门，屋内的人声停止了。片刻后，一个苍老的声音问：‘谁在敲门？’你回答说自己迷路了，请求帮助。门缓缓打开，一个慈祥的老人邀请你进屋，但你注意到他的眼神中有一丝警惕。你成功进入了小屋，但老人似乎对你的出现有所防备。",
      "result": "partial",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "在窗外偷听",
      "outcome": "你决定在窗外偷听，小心翼翼地靠近。透过窗帘的缝隙，你看到屋内有两个人正在商量如何帮助一个迷路的孩子。他们的话语让你感到温暖，也明白了为什么窗帘遮得这么严实——他们希望孩子能安心休息。你悄悄离开，决定回去寻找迷路的孩子，然后带他来求助。",
      "result": "success",
      "next": "next_level"
    }
  ]
}
